entries[5642] = { ["name"] = "Rezept: Trank der freien Aktion", ["text"] = "Benötigt Alchemie\n(150)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der freien Aktion.\nTrank der freien Aktion\nBenötigt Stufe 20\nBenutzen: Macht Euch 30 sec lang immun gegen betäubungs- und bewegungseinschränkende Effekte. Bereits bestehende Effekte dieser Art werden nicht entfernt. (1 Min Abklingzeit)\nBenötigt Schwarzmaulöl (2), Würgetang , Verbleite Phiole" }
