entries[5644] = { ["name"] = "Foliant des Wasserherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 4\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 1).\nZaubert 20 Flaschen Wasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes Wasser\nHerbeigezauberter Gegenstand\nBenutzen: Stellt im Verlauf von 18 sec insgesamt 151 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[5645] = { ["name"] = "Gefüllte Turmalinphiole", ["text"] = "Questgegenstand\nEinzigartig" }
entries[5646] = { ["name"] = "Phiole mit gesegnetem Wasser", ["text"] = "Questgegenstand\nEinzigartig" }
entries[5647] = { ["name"] = "Foliant des Blinzelns", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Blinzeln' (Rang 1).\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungen und Fesseln." }
entries[5648] = { ["name"] = "Foliant der Frostrüstung III", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Frostrüstung' (Rang 3).\nErhöht die Rüstung um 200. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[5649] = { ["name"] = "Foliant des Blizzards", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Blizzard' (Rang 1).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 sec lang insgesamt [Quellwert] Frostschaden.", ["unresolvedValues"] = true }
entries[5650] = { ["name"] = "Foliant des Wasserherbeizauberns III", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 3).\nZaubert 20 Flaschen geläutertes Wasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes geläutertes Wasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 15\nBenutzen: Stellt im Verlauf von 24 sec insgesamt 835 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[5654] = { ["name"] = "Sofort wirkendes Toxin", ["text"] = "Klassen: Schurke\nBenötigt Stufe 24\nBenutzen: Überzieht ein Schwert oder einen Dolch mit Gift, das 30 Minuten lang wirkt.\nBei jedem Schlag besteht die Chance, den Feind zu vergiften und ihm sofort 10-30 Punkte Schaden zuzufügen." }
