entries[5672] = { ["name"] = "Buchband: Exorzismus", ["text"] = "Klassen: Paladin\nBenötigt Stufe 20\nBenutzen: Lehrt 'Exorzismus' (Rang 1).\nVerursacht (96 + 0.15 * Spell power + 0.15 * Attack power) bis (110 + 0.15 * Spell power + 0.15 * Attack power) Heiligschaden an einem feindlichen Ziel. Ist das Ziel untot oder dämonisch wird der Zauber stets kritisch treffen." }
entries[5673] = { ["name"] = "Buchband: Exorzismus II", ["text"] = "Klassen: Paladin\nBenötigt Stufe 28\nBenutzen: Lehrt 'Exorzismus' (Rang 2).\nVerursacht (173 + 0.15 * Spell power + 0.15 * Attack power) bis (195 + 0.15 * Spell power + 0.15 * Attack power) Heiligschaden an einem feindlichen Ziel. Ist das Ziel untot oder dämonisch wird der Zauber stets kritisch treffen." }
