entries[5676] = { ["name"] = "Buchband: Untote spüren", ["text"] = "Klassen: Paladin\nBenötigt Stufe 20\nBenutzen: Lehrt 'Untote spüren'.\nZeigt den Aufenthaltsort aller in der Nähe befindlicher Untoter auf der Minikarte an, bis abgebrochen wird. Es kann immer nur jeweils eine Art des Fährtenlesens benutzt werden." }
