entries[5684] = { ["name"] = "Buchband: Siegel der Rettung", ["text"] = "Klassen: Paladin\nBenötigt Stufe 22\nBenutzen: Lehrt 'Siegel der Rettung' (Rang 1).\nLegt eine Hand auf das Gruppen- und Schlachtzugsmitglied und verringert 10 sec lang alle 1 Sek. seine gesamte Bedrohung um 2%. Spieler können pro Paladin immer nur von einer Hand berührt werden." }
