entries[5696] = { ["name"] = "Schrifttafel des Schocks", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Schock' (Rang 1).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 25 to 28 Schaden zu." }
entries[5697] = { ["name"] = "Schrifttafel des Totems der Heilung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Totem der Heilung' (Rang 1).\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Gruppenmitglieder im Umkreis von 30 Metern erhalten alle 2 Sek. 6 Gesundheit. Hält 5 min lang an." }
entries[5698] = { ["name"] = "Schrifttafel des Blitzschlagschildes", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 1).\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifende 13 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 min lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)" }
entries[5699] = { ["name"] = "Schrifttafel des Geisterwolfs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 12\nBenutzen: Lehrt 'Geisterwolf' (Rang 1).\nVerwandelt den Schamanen in einen Geisterwolf und erhöht sein Tempo um 40%\n\nGlyphe 'Geisterwolf'\nund regeneriert alle 5 Sek. 1% der maximalen Gesundheit\n\nAls Geisterwolf wird der Schamane durch Effekte, die sein Bewegungstempo einschränken, weniger gehindert. Kann nur draußen verwendet werden." }
entries[5700] = { ["name"] = "Schrifttafel des Totems der Heilung II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 12\nBenutzen: Lehrt 'Totem der Heilung' (Rang 2).\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Gruppenmitglieder im Umkreis von 30 Metern erhalten alle 2 Sek. 8 Gesundheit. Hält 5 min lang an." }
entries[5701] = { ["name"] = "Schrifttafel des Totem des Wachens", ["text"] = "Klassen: Schamane\nBenötigt Stufe 14\nBenutzen: Lehrt 'Totem des Wachens'.\nBeschwört für 5 min ein unbewegliches Totem des Wachens mit 100 Gesundheit zu Euren Füßen, das die Sicht auf die in der Nähe befindlichen Bereiche ermöglicht und vor Feinden warnt, die es angreifen. Mit einem Rechtsklick auf den Stärkungszauber kann zwischen dem Blickwinkel des Totems und dem Blickwinkel des Schamanen gewechselt werden." }
entries[5702] = { ["name"] = "Schrifttafel des aufstachelnden Totems II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 18\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 2).\nBeschwört für 15 sec ein Totem der Steinklaue mit [150 + floor(Stamina * 0.05)] Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, für 3 sec betäubt werden. Das Totem der Steinklaue beschützt außerdem all Eure Totems, wodurch sie 58 Schaden absorbieren." }
entries[5703] = { ["name"] = "Schrifttafel des Donnerknalls", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Donnerknall' (Rang 1).\nTrifft nahe Feinde, erhöht die Zeit zwischen ihren Angriffen 10 sec lang um 10% und verursacht 15 Schaden. Schaden wird durch Angriffskraft erhöht. Diese Fähigkeit verursacht zusätzliche Bedrohung." }
entries[5704] = { ["name"] = "Schrifttafel der Wasseratmung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Wasseratmung'.\nErmöglicht dem Ziel 10 min lang das Atmen unter Wasser." }
entries[5705] = { ["name"] = "Schrifttafel des Totems der Heilung III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Totem der Heilung' (Rang 3).\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Gruppenmitglieder im Umkreis von 30 Metern erhalten alle 2 Sek. 10 Gesundheit. Hält 5 min lang an." }
entries[5706] = { ["name"] = "Schrifttafel des Schlangentotems III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Totem der Schlange' (Rang 3).\nBeschwört 40 sec lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 19 to 25 Punkt(e) Feuerschaden anrichtet." }
entries[5707] = { ["name"] = "Schrifttafel der Fernsicht", ["text"] = "Klassen: Schamane\nBenötigt Stufe 26\nBenutzen: Lehrt 'Fernsicht'.\nWechselt die Ansicht des Zaubernden zum Zielort. Hält 1 min lang an. Kann nur draußen verwendet werden." }
entries[5708] = { ["name"] = "Schrifttafel der Astralgestalt", ["text"] = "Klassen: Schamane\nBenötigt Stufe 24\nBenutzen: Lehrt 'Astralgestalt' (Rang 1)." }
entries[5709] = { ["name"] = "Schrifttafel des Wasserwandelns", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Wasserwandeln'.\nErmöglicht dem befreundeten Ziel, 10 min lang auf Wasser zu wandern. Jeglicher erlittene Schaden hebt den Effekt wieder auf." }
entries[5710] = { ["name"] = "Schrifttafel des Totems der Heilung IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Totem der Heilung' (Rang 4)." }
entries[5711] = { ["name"] = "Schrifttafel des Geisterwolfs II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Geisterwolf' (Rang 2)." }
entries[5712] = { ["name"] = "Schrifttafel des Schlangentotems IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Totem der Schlange' (Rang 4).\nBeschwört 45 sec lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 26 to 34 Punkt(e) Feuerschaden anrichtet." }
entries[5713] = { ["name"] = "Schrifttafel des Donnerblitzes", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Donnerblitz'.\nSchützt das befreundete Ziel gegen Furcht. Der nächste Furchteffekt gegen das Ziel ist erfolglos, dabei wird der Zauberschutz verbraucht. Hält 3 min lang an." }
