entries[5715] = { ["name"] = "Schrifttafel des Gewittersturms III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Gewittersturm' (Rang 3)." }
entries[5716] = { ["name"] = "Schrifttafel der Wiederherstellung VI", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Große Welle der Heilung' (Rang 2).\nHeilt ein befreundetes Ziel um 552 to 639." }
