entries[5719] = { ["name"] = "Zauberfoliant des Lebenssaugers II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Blutsauger' (Rang 2).\nÜberträgt alle 1 Sek. 17 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
entries[5720] = { ["name"] = "Zauberfoliant des Fluchs von Mannoroth II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Fluch der Schwäche' (Rang 2).\nDie Nahkampfangriffskraft des Ziels wird um 41 verringert, seine Rüstung um 5%. Hält 2 min lang an. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[5721] = { ["name"] = "Zauberfoliant der Zaubersteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 34\nBenutzen: Lehrt 'Zauberstein herstellen'.\nErhöht bei Anwendung auf eine Waffe den Schaden regelmäßiger Zauber um 1% und die Zaubertempowertung um 10. Hält 1 Stunde lang an.\nZauberstein\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhöht bei Anwendung auf eine Waffe den Schaden regelmäßiger Zauber um 1% und die Zaubertempowertung um 10. Hält 1 Stunde lang an.\n5 AufladungenBenötigt Seelensplitter" }
entries[5722] = { ["name"] = "Zauberfoliant des Manaentzugs II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 36\nBenutzen: Lehrt 'Mana entziehen' (Rang 2)." }
entries[5723] = { ["name"] = "Zauberfoliant des Fluchs von Sargeras III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 36\nBenutzen: Lehrt 'Fluch der Pein' (Rang 3).\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 324 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[5724] = { ["name"] = "Zauberfoliant des Fluchs der Sprachen", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Fluch der Sprachen' (Rang 1).\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 25%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 sec lang an." }
entries[5725] = { ["name"] = "Zauberfoliant der Pestilenz III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 38\nBenutzen: Lehrt 'Verderbnis' (Rang 3).\nVerdirbt das Ziel und verursacht 18 sec lang insgesamt 222 Schattenschaden." }
entries[5726] = { ["name"] = "Zauberfoliant der großen Blutsteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 38\nBenutzen: Lehrt 'Großen Gesundheitsstein herstellen'." }
entries[5727] = { ["name"] = "Zauberfoliant des Manatrichters", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Manatrichter'." }
entries[5728] = { ["name"] = "Zauberfoliant des Feuerregens II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Feuerregen' (Rang 2).\nLässt einen feurigen Regen niedergehen, der 8 sec lang Feinde im Wirkungsbereich mit insgesamt ( 138 * 4) Feuerschaden verbrennt." }
entries[5729] = { ["name"] = "Zauberfoliant der Furcht III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Furcht' (Rang 3).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 20 sec lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[5730] = { ["name"] = "Buch der Verjüngung", ["text"] = "Klassen: Druide\nBenötigt Stufe 4\nBenutzen: Lehrt 'Verjüngung' (Rang 1).\nHeilt im Verlauf von 15 sec um [Quellwert] Gesundheit.", ["unresolvedValues"] = true }
